"""Render the public HTML. No template engine or runtime dependencies."""
from pathlib import Path
from html import escape
from urllib.parse import quote
import json
import re
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[1]
BASE = 'https://gabrielsantanabr.github.io/dataforge-portfolio/'
GITHUB = 'https://github.com/GabrielSantanaBR/'
LINKEDIN = 'https://www.linkedin.com/in/gabriel-santana-b3654622a/'
DESCRIPTION = 'A MATRIZ desenvolve sistemas, automações, soluções de dados, inteligência artificial e produtos digitais para transformar operações em tecnologia.'
ALL_PROJECTS = json.loads((ROOT/'content/projects.json').read_text())
PROJECTS = [p for p in ALL_PROJECTS if p.get('listed', True)]
CASES = [p for p in ALL_PROJECTS if p.get('page')]
VISIBLE_CASES = [p for p in PROJECTS if p.get('page')]
FEATURED = [p for p in PROJECTS if p.get('featured')]
DATE = '2026-09-09'

def contact_bundle():
    """Ship a single deferred script; keep the contact core importable in tests."""
    core=(ROOT/'assets/js/contact-core.js').read_text()
    ui=(ROOT/'assets/js/contact.js').read_text()
    assert ui.startswith('import {')
    script="// Generated by scripts/render.py from contact-core.js and contact.js.\n(() => {\n'use strict';\n"
    script+=re.sub(r'^export ', '', core, flags=re.MULTILINE)+'\n'+ui.split('\n',1)[1]+'\n})();\n'
    (ROOT/'assets/js/contact-bundle.js').write_text(script)

def e(s): return escape(str(s), quote=True)
def external(url, label, cls=''): return f'<a href="{e(url)}" target="_blank" rel="noopener noreferrer" class="{cls}">{label}</a>'
def repo_url(p): return GITHUB+p['repo']+('/tree/'+p['branch'] if p.get('branch') else '')
def brand(): return '<a class="brand" href="index.html" aria-label="MATRIZ — início"><img src="assets/brand/logo-matriz.png" alt="" width="47" height="47"><strong itemprop="name">MATRIZ</strong></a>'
def action(href,label,primary=False): return f'<a class="button {"primary" if primary else "secondary"}" href="{e(href)}">{label}<span aria-hidden="true">↗</span></a>'
def nav(active):
    links=[('index.html#solucoes','Soluções'),('index.html#projetos','Projetos'),('index.html#processo','Como funciona')]
    navlinks=''.join(f'<a href="{url}"'+(' aria-current="page"' if active==url else '')+f'>{label}</a>' for url,label in links)
    return f'''<a class="skip-link" href="#main-content">Pular para o conteúdo</a>
<header class="site-header"><div class="container header-inner">{brand()}
<button class="menu-toggle" type="button" aria-controls="main-nav" aria-expanded="false" aria-label="Abrir menu"><span>Menu</span><i aria-hidden="true"></i></button>
<nav class="main-nav" id="main-nav" aria-label="Navegação principal">{navlinks}<a class="mobile-contact" href="contact.html">Pedir uma proposta ↗</a></nav>
<a class="button header-cta" href="contact.html">Pedir uma proposta <span aria-hidden="true">↗</span></a></div><span class="scroll-progress" aria-hidden="true"></span></header>'''
def footer(): return f'''<footer class="site-footer"><div class="container"><div class="footer-top"><div class="footer-brand">{brand()}<p>Sistemas · Automação · Dados · Inteligência.</p></div><div class="footer-links"><p class="label">Explore</p><a href="index.html#solucoes">Soluções</a><a href="index.html#projetos">Projetos</a><a href="repertoire.html">Portfólio completo</a><a href="prices.html">Serviços</a></div><div class="footer-links"><p class="label">Conecte-se</p><a href="contact.html">Contato</a>{external(GITHUB.rstrip('/'),'GitHub ↗')}{external(LINKEDIN,'LinkedIn ↗')}<a href="privacy.html">Privacidade</a><a href="security.html">Segurança</a></div></div><div class="footer-bottom"><span>© <span id="year" data-year>2026</span> MATRIZ. Tecnologia aplicada.</span><span>Projetos sob medida, do início à evolução.</span></div><div class="footer-wordmark" aria-hidden="true">MATRIZ</div></div></footer>'''
def write_page(path,title,description,body,*,noindex=False,contact=False):
    url=BASE+('' if path=='index.html' else path)
    csp="default-src 'self'; base-uri 'none'; object-src 'none'; frame-src 'none'; media-src 'none'; worker-src 'none'; font-src 'self'; img-src 'self'; style-src 'self'; script-src 'self'; connect-src "+("https://api.web3forms.com" if contact else "'none'")+"; form-action "+("https://api.web3forms.com" if contact else "'none'")+"; upgrade-insecure-requests"
    html=f'''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta http-equiv="Content-Security-Policy" content="{csp}"><meta name="referrer" content="strict-origin-when-cross-origin"><meta name="theme-color" content="#0A0B0D"><meta name="color-scheme" content="dark"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow'}"><title>{e(title)}</title><meta name="description" content="{e(description)}"><link rel="canonical" href="{url}">
<meta property="og:locale" content="pt_BR"><meta property="og:type" content="website"><meta property="og:site_name" content="MATRIZ"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}assets/brand/logo-matriz.png"><meta property="og:image:width" content="1254"><meta property="og:image:height" content="1254"><meta property="og:image:alt" content="Símbolo oficial da MATRIZ: cubo branco e chama vermelha, laranja e amarela."><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)}"><meta name="twitter:description" content="{e(description)}"><meta name="twitter:image" content="{BASE}assets/brand/logo-matriz.png">
<link rel="icon" href="assets/brand/logo-matriz.png" type="image/png" sizes="1254x1254"><link rel="apple-touch-icon" href="assets/brand/logo-matriz.png"><link rel="manifest" href="site.webmanifest"><link rel="stylesheet" href="assets/css/matriz.css"><script src="assets/js/site.js" defer></script>{'<script src="assets/js/contact-bundle.js" defer></script>' if contact else ''}</head>
<body class="page-{'home' if path == 'index.html' else path.removesuffix('.html')}" itemscope itemtype="https://schema.org/Organization"><meta itemprop="url" content="{BASE}">{nav(path)}<main id="main-content">{body}</main>{footer()}</body></html>'''
    if path=='404.html':
        # A Pages 404 is also served for arbitrarily nested URLs.
        import re
        html=re.sub(r'((?:href|src)=")(?!(?:https?:|#))([^\"]+)',lambda m:m[1]+'/dataforge-portfolio/'+m[2],html)
    (ROOT/path).write_text(html+'\n')

def architecture(p):
    boxes='<span aria-hidden="true">→</span>'.join(f'<b>{e(x)}</b>' for x in p['diagram'])
    return f'<div class="architecture-art"><div class="label">{e(p["name"])} / fluxo da solução</div><div class="architecture-flow">{boxes}</div><p>{e(" · ".join(p["stack"][:3]))}</p><div class="architecture-note">Diagrama de funcionamento</div></div>'
def visual(p):
    image=p.get('image')
    if image:return f'<img src="{e(image)}" alt="{e(p["image_alt"])}" width="{p.get('image_width',1440)}" height="{p.get('image_height',900)}" loading="lazy" decoding="async">'
    return architecture(p)
def case_tile(p,large=False):
    preview_note={'concept':'Referência visual','anonymized':'Imagem anonimizada'}.get(p.get('image_kind'))
    preview_badge=f'<span class="preview-note">{preview_note}</span>' if preview_note else ''
    image_class=' has-image' if p.get('image') else ''
    if large:return f'''<article class="case large reveal"><a class="case-visual" href="{p['page']}" aria-label="Conhecer o projeto {e(p['name'])}">{visual(p)}</a><div class="case-copy"><p class="label">Projeto em foco / {e(p['category'])}</p><h3><a href="{p['page']}">{e(p['name'])}</a></h3><p>{e(p['summary'])}</p><div class="case-meta"><span class="status-tag">{e(p['status'])}</span></div><a class="text-link" href="{p['page']}">Conhecer o projeto <span aria-hidden="true">↗</span></a></div></article>'''
    return f'''<article class="case reveal{image_class}"><a href="{p['page']}" aria-label="Conhecer o projeto {e(p['name'])}"><div class="case-visual">{visual(p)}{preview_badge}</div><div class="case-caption"><h3>{e(p['name'])}</h3><span aria-hidden="true">↗</span></div></a><p>{e(p['summary'])}</p><div class="case-meta"><span>{e(p['category'])}</span><span class="status-tag">{e(p['status'])}</span></div></article>'''
def cta():return f'''<section class="contact-band"><div class="container"><div><p class="label">Vamos conversar</p><h2 id="cta-title">Seu próximo passo<br>começa com uma ideia.</h2><p>Conte o que você precisa. O escopo a gente constrói junto.</p></div>{action('contact.html','Pedir uma proposta')}</div></section>'''

def repertoire_rows():
    categories=['Todos']+[c for c in ['Sistemas','Automação','Dados','IA','Backend','Web'] if any(p['category']==c for p in PROJECTS)]
    filters=''.join(f'<button class="filter-button" type="button" data-filter="{e(cat)}" aria-pressed="{str(cat=="Todos").lower()}">{cat}</button>' for cat in categories)
    rows=''.join(f'<a class="repo-row" href="{repo_url(p)}" target="_blank" rel="noopener noreferrer" data-category="{e(p["category"])}" data-repo="{e(p["repo"])}"'+(' data-kind="fork"' if p.get('fork') else '')+f'><h3>{e(p["name"])}</h3><p>{e(p["summary"])}</p><span class="repo-kind">{e(p["status"])}</span><span aria-hidden="true">↗</span></a>' for p in PROJECTS)
    return f'<div class="filter-bar"><div class="filters" role="group" aria-label="Filtrar repertório por área">{filters}</div><p class="result-count" id="repo-count" aria-live="polite" role="status">{len(PROJECTS)} repositórios</p></div><div class="repertoire">{rows}</div>'

def home():
    needs=[('web','Quero um site','Apresente seu negócio e facilite o contato de novos clientes.'),('sistemas','Quero organizar a operação','Reúna pedidos, clientes e processos em um sistema.'),('automacao','Quero automatizar tarefas','Conecte ferramentas e reduza o trabalho repetitivo.'),('dados','Quero decidir com dados','Transforme suas informações em painéis e análises úteis.')]
    solutions=''.join(f'<a class="need-link reveal" href="contact.html?service={key}"><span class="need-number" aria-hidden="true">0{i}</span><div><h3>{title}</h3><p>{description}</p></div><span class="need-arrow" aria-hidden="true">↗</span></a>' for i,(key,title,description) in enumerate(needs,1))
    selected_projects=[next(p for p in PROJECTS if p['repo']==repo) for repo in ['coffee_five_site','projeto-petshop','nossas-delicias-site']]
    selected=''.join(case_tile(p) for p in selected_projects)
    process=[('Uma conversa','Entendemos sua necessidade e o que tem prioridade.'),('Uma proposta clara','Você conhece escopo, etapas e investimento antes de começar.'),('Uma solução funcionando','Construímos, testamos e acompanhamos a entrega combinada.')]
    steps=''.join(f'<article class="process-step reveal"><p class="label">0{i}</p><h3>{name}</h3><p>{description}</p></article>' for i,(name,description) in enumerate(process,1))
    body=f'''<section class="hero container" id="inicio"><div class="hero-layout"><div class="hero-copy"><p class="eyebrow label reveal">Tecnologia sob medida</p><h1 class="reveal">Seu negócio.<br><span class="last-word">Próximo nível.</span></h1><p class="reveal"><span>Sites para se destacar.</span> <span>Sistemas para organizar.</span><br><span>Automação e dados para ganhar tempo.</span></p><div class="actions reveal">{action('contact.html','Pedir uma proposta',True)}<a class="text-link" href="#projetos">Ver projetos <span aria-hidden="true">↗</span></a></div></div><div class="hero-graphic" aria-label="Símbolo oficial da MATRIZ"><img class="hero-logo" src="assets/brand/logo-matriz.png" alt="Cubo branco com chama em vermelho, laranja e amarelo, símbolo da MATRIZ" width="1254" height="1254" fetchpriority="high"><i class="ember-particle" aria-hidden="true"></i><i class="ember-particle two" aria-hidden="true"></i><i class="ember-particle three" aria-hidden="true"></i></div></div></section>
<section class="section needs-section" id="solucoes"><span id="desafios"></span><span id="servicos"></span><div class="container"><div class="section-top reveal"><div><p class="eyebrow label">O que você precisa?</p><h2>Encontre seu<br><span class="accent">próximo passo.</span></h2></div><a class="text-link" href="prices.html">Todos os serviços <span aria-hidden="true">↗</span></a></div><div class="needs-grid">{solutions}</div></div></section>
<section class="section selected-section" id="projetos"><span id="cases"></span><div class="container"><div class="section-top reveal"><div><p class="eyebrow label">Projetos selecionados</p><h2 id="proof-title">Veja as ideias<br>ganharem forma.</h2></div><p>Uma amostra do que construímos.<br>Conheça a proposta e o estágio de cada projeto.</p></div><div class="selected-grid">{selected}</div><div class="portfolio-link" id="repertorio"><span id="repositorios"></span><a class="text-link" href="repertoire.html">Ver o portfólio completo <span aria-hidden="true">↗</span></a></div></div></section>
<section class="section process-section" id="processo"><div class="container"><div class="section-top reveal"><div><p class="eyebrow label">Como funciona</p><h2>Clareza do primeiro<br>contato à entrega.</h2></div></div><div class="process-grid">{steps}</div><div class="studio-note" id="sobre"><strong>MATRIZ</strong><p>Dados, desenvolvimento e segurança na mesma base.<br>Tecnologia pensada para quem vai usar.</p></div></div></section>{cta()}'''
    write_page('index.html','MATRIZ — Sites, Sistemas e Automação sob medida',DESCRIPTION,body)

def project_pages():
    for i,p in enumerate(CASES):
        if p['repo']=='Sicma-JAVA':
            sicma_page(p)
            continue
        features=''.join(f'<li>{e(x)}</li>' for x in p['features'])
        flow=''.join(f'<li><h3>{e(a)}</h3><p>{e(b)}</p></li>' for a,b in p['flow'])
        stack=''.join(f'<span>{e(x)}</span>' for x in p['stack'])
        sources=' · '.join(external(GITHUB+p['repo']+'/blob/'+p.get('branch','main')+'/'+quote(path),e(path)) for path in p['evidence'])
        visible_index=next((i for i,item in enumerate(VISIBLE_CASES) if item['repo']==p['repo']),-1)
        nxt=VISIBLE_CASES[(visible_index+1)%len(VISIBLE_CASES)]
        screenshot=(f'<figure class="case-screenshot"><a href="{p["image"]}" target="_blank" rel="noopener noreferrer" aria-label="Ampliar imagem de {e(p["name"])}"><img src="{p["image"]}" alt="{e(p["image_alt"])}" width="{p.get("image_width",1440)}" height="{p.get("image_height",900)}" loading="lazy"></a><figcaption>{e(p.get("image_note","Captura real da interface do repositório."))} <a class="expand-image" href="{p["image"]}" target="_blank" rel="noopener noreferrer">Ampliar imagem ↗</a></figcaption></figure>' if p.get('image') else '')
        body=f'''<div class="container"><section class="page-hero"><div class="breadcrumb"><a href="index.html">MATRIZ</a><span>/</span><a href="index.html#projetos">Projetos</a><span>/</span><span>{e(p['name'])}</span></div><p class="eyebrow label">{e(p['category'])} / {e(p['name'])}</p><h1>{e(p['headline'])}</h1><p>{e(p['summary'])}</p><div class="case-meta"><span class="status-tag">{e(p['status'])}</span><span>Inspecionado em 08/09/2026</span></div><div class="actions">{action('contact.html?service='+p['service']+'&project='+quote(p['name']),'Quero uma solução assim',True)}{external(repo_url(p),'Ver código <span aria-hidden="true">↗</span>','button secondary')}{external(p['demo'],'Abrir demonstração <span aria-hidden="true">↗</span>','button secondary') if p.get('demo') else ''}</div></section>
<div class="case-layout"><aside class="case-index" aria-label="Nesta página"><p class="label">Dentro do projeto</p><a href="#visao">Visão geral</a><a href="#fluxo">Como funciona</a><a href="#recursos">Capacidades</a><a href="#arquitetura">Tecnologia e arquitetura</a><a href="#status">Status e evolução</a></aside><div class="case-content"><section class="case-section" id="visao">{screenshot}<div class="two-cols"><div><p class="eyebrow label">O problema</p><h2>O que precisa mudar?</h2><p>{e(p['problem'])}</p></div><div><p class="eyebrow label">A solução</p><h2>O que foi construído.</h2><p>{e(p['solution'])}</p></div></div></section><section class="case-section" id="fluxo"><h2>Como funciona.</h2><ol class="case-flow">{flow}</ol></section><section class="case-section" id="recursos"><h2>Capacidades do projeto.</h2><ul class="feature-list">{features}</ul></section><section class="case-section" id="arquitetura"><h2>A engenharia por trás.</h2><p>{e(p['architecture'])}</p><div class="tech-list">{stack}</div>{architecture(p)}</section><section class="case-section" id="status"><h2>O estágio atual. O próximo passo.</h2><p class="source-note">{e(p['limits'])}</p><h3>Possibilidades de evolução</h3><p>{e(p['evolution'])}</p><p class="research-note">Fontes consultadas: {sources}.</p></section><a class="case-next" href="{nxt['page']}"><div><p class="label">Próximo projeto</p><strong>{e(nxt['name'])}</strong></div><span aria-hidden="true">↗</span></a></div></div></div>{cta()}'''
        write_page(p['page'],p['name']+' — Projetos MATRIZ',p['summary'],body,noindex=not p.get('listed',True))

def sicma_page(p):
    body=f'''<div class="container"><section class="page-hero"><div class="breadcrumb"><a href="index.html">MATRIZ</a><span>/</span><a href="repertoire.html">Portfólio</a><span>/</span><span>SICMA</span></div><p class="eyebrow label">Java / Spring Boot</p><h1>SICMA</h1><p>Um projeto em desenvolvimento.<br>A próxima versão está em preparação.</p><div class="case-meta"><span class="status-tag">Em desenvolvimento</span></div><div class="actions">{external(repo_url(p),'Acompanhar no GitHub <span aria-hidden="true">↗</span>','button primary')}<a class="text-link" href="repertoire.html">Voltar ao portfólio <span aria-hidden="true">↗</span></a></div></section><section class="case-section sicma-status"><h2>Acompanhe a construção.</h2><p>O repositório público já contém a estrutura inicial em Java 17, Spring Boot e Gradle. A implementação do sistema será adicionada em uma próxima atualização.</p><p>Quando a nova versão estiver disponível, esta página poderá apresentar suas funcionalidades e demonstração.</p><div class="tech-list"><span>Java 17</span><span>Spring Boot</span><span>Gradle</span></div></section></div>{cta()}'''
    write_page('sicma.html','SICMA — Projeto Java | MATRIZ',p['summary'],body)

def contact_page():
    options=[('sistemas','Sistema'),('automacao','Automação'),('dados','Dados / BI'),('ia','Inteligência Artificial'),('web','Site / Produto Web'),('api','API / Backend'),('mvp','MVP'),('evolucao','Evolução tecnológica'),('outro','Outro')]
    fields=''.join(f'<option value="{key}">{val}</option>' for key,val in options)
    body=f'''<div class="container"><section class="page-hero"><div class="breadcrumb"><a href="index.html">MATRIZ</a><span>/</span><span>Contato</span></div><p class="eyebrow label">Seu projeto começa aqui</p><h1>O que vamos<br><span class="accent">construir juntos?</span></h1><p>Conte o que você precisa. Vamos entender sua ideia e preparar o próximo passo.</p></section><div class="contact-layout">
<form class="contact-form" id="secure-contact-form" action="https://api.web3forms.com/submit" method="post" accept-charset="UTF-8"><input type="hidden" name="access_key" value="c4f95a43-ff78-42b8-be6f-e58c32be1a8d"><input type="hidden" name="subject" value="Novo contato — MATRIZ"><input type="hidden" name="from_name" value="Site MATRIZ"><input type="hidden" name="redirect" value="{BASE}thanks.html"><div class="honeypot" aria-hidden="true"><label for="botcheck">Deixe este campo vazio</label><input id="botcheck" type="checkbox" name="botcheck" tabindex="-1" autocomplete="off"></div>
<div class="field-row"><div class="field"><label for="name">Nome</label><input id="name" name="name" aria-describedby="name-error" required minlength="2" maxlength="80" autocomplete="name" placeholder="Como podemos chamar você?"><p class="form-error" id="name-error" hidden></p></div><div class="field"><label for="email">Email</label><input id="email" aria-describedby="email-error" type="email" name="email" required maxlength="160" autocomplete="email" placeholder="voce@empresa.com.br" spellcheck="false"><p class="form-error" id="email-error" hidden></p></div></div><div class="field"><label for="service">Tipo de projeto</label><select id="service" name="service" aria-describedby="service-error" required><option value="">Selecione uma opção</option>{fields}</select><p class="form-error" id="service-error" hidden></p></div><div class="field"><label for="message">Qual problema você quer resolver?</label><textarea id="message" name="message" required minlength="30" maxlength="2500" aria-describedby="message-help message-error" placeholder="Conte como funciona hoje, o que toma tempo e qual resultado você espera alcançar."></textarea><p class="help" id="message-help">De 30 a 2.500 caracteres. Não inclua senhas, documentos ou informações sensíveis.</p><p class="form-error" id="message-error" hidden></p></div><details class="contact-optional"><summary>Adicionar informações opcionais</summary><div class="optional-fields"><div class="field"><label for="company">Empresa <span class="optional">(opcional)</span></label><input id="company" name="company" maxlength="100" autocomplete="organization" placeholder="Seu negócio ou projeto"></div><div class="field"><label for="phone">WhatsApp <span class="optional">(opcional)</span></label><input id="phone" name="phone" aria-describedby="phone-error" type="tel" maxlength="25" autocomplete="tel" placeholder="(21) 99999-9999"><p class="form-error" id="phone-error" hidden></p></div><div class="field"><label for="budget">Investimento previsto <span class="optional">(opcional)</span></label><input id="budget" name="budget" maxlength="100" placeholder="Uma faixa ou “ainda não defini”"><p class="help">Uma referência para entender o escopo. Não define um preço automático.</p></div></div></details><p class="consent-note">Usaremos seus dados para responder ao contato e avaliar o projeto. O envio é processado pelo Web3Forms. Saiba mais na <a href="privacy.html">política de privacidade</a>.</p><button class="button primary submit-button" type="submit">Enviar para a MATRIZ <span aria-hidden="true">↗</span></button><p class="form-status" id="form-status" role="status" aria-live="polite" aria-atomic="true"></p><noscript><p class="consent-note">O formulário continua disponível sem JavaScript. O serviço de envio abrirá após a validação do navegador.</p></noscript></form><aside class="contact-aside"><h2>Não precisa ter<br>tudo definido.</h2><p>Uma ideia ou um problema da rotina já são um bom começo.</p><p>Antes de iniciar, você recebe uma proposta com escopo, etapas e investimento.</p>{external(LINKEDIN,'Conheça quem está por trás <span aria-hidden="true">↗</span>','text-link')}</aside></div></div>'''
    write_page('contact.html','Fale com a MATRIZ — Sistemas, Dados e Automação','Conte o problema que você quer resolver. Vamos entender sua operação e definir um escopo de tecnologia para o próximo passo.',body,contact=True)

def services_page():
    stages=[('Diagnóstico','Entendemos os processos, os usuários e as prioridades. O objetivo é definir um problema concreto e um escopo viável.'),('MVP e desenvolvimento','Construímos a primeira versão utilizável com entregas e critérios de aceite definidos. A complexidade orienta prazo e investimento.'),('Evolução e manutenção','Após a validação, planejamos melhorias, integrações e acompanhamento. A continuidade é combinada conforme a necessidade da operação.')]
    row=''.join(f'<li><span class="label">0{i}</span><h2>{a}</h2><p>{b}</p></li>' for i,(a,b) in enumerate(stages,1))
    services=[('Sistemas e gestão','Sistemas internos, CRMs, financeiros, painéis operacionais, portais, SaaS e workflows.','sistemas'),('Automação e integração','Processamento, ETL, planilhas inteligentes, notificações e relatórios recorrentes.','automacao'),('Dados e BI','Dashboards, KPIs, modelagem, pipelines, qualidade de dados, precificação e análise.','dados'),('Inteligência Artificial','Previsão, classificação, recomendação, segmentação, anomalias e IA generativa aplicada.','ia'),('Sites e produtos web','Institucionais, landing pages, vitrines, cardápios, ecommerce e PWA.','web'),('Backend e APIs','APIs REST, bancos, autenticação, regras de negócio e integrações entre ferramentas.','api'),('MVPs para nichos','Validação de soluções para academias, pet shops, cafeterias, confeitaria e serviços.','mvp'),('Infraestrutura e evolução','Deploy, Docker, CI, cloud, modernização, revisão de segurança e performance.','evolucao')]
    rows=''.join(f'<a class="service-item" href="contact.html?service={key}"><h3>{name}</h3><p>{text}</p><span aria-hidden="true">↗</span></a>' for name,text,key in services)
    body=f'''<div class="container"><section class="page-hero"><div class="breadcrumb"><a href="index.html">MATRIZ</a><span>/</span><span>Serviços</span></div><p class="eyebrow label">Soluções sob escopo</p><h1>Tecnologia estruturada<br><span class="accent">para crescer.</span></h1><p>Do diagnóstico à evolução. Construímos o que sua operação precisa, com escopo, etapas e investimento definidos antes de começar.</p><div class="actions">{action('contact.html','Conversar sobre um projeto',True)}<span class="label">Projeto sob orçamento</span></div></section><section class="case-section"><h2>Como o trabalho é organizado.</h2><ol class="brief-list">{row}</ol></section><section class="case-section"><h2>O que podemos construir.</h2><div class="service-grid">{rows}</div></section><section class="case-section"><div class="two-cols"><div><h2>O que define o investimento?</h2><p>O número de fluxos, os usuários envolvidos, as integrações, a disponibilidade dos dados e os requisitos de segurança. Uma conversa inicial ajuda a dimensionar essas variáveis.</p></div><div><h2>O que entra na proposta?</h2><p>Objetivo, entregas, critérios de aceite, responsabilidades, cronograma e condições de evolução. Hospedagem, licenças e serviços de terceiros são identificados quando necessários.</p></div></div></section></div>{cta()}'''
    write_page('prices.html','Serviços — MATRIZ | Projetos sob escopo','Sistemas, automação, dados, IA, produtos web e APIs. Diagnóstico, desenvolvimento e evolução com projeto sob orçamento.',body)

def editorial_pages():
    intro=lambda label,title,desc:f'<section class="page-hero"><div class="breadcrumb"><a href="index.html">MATRIZ</a><span>/</span><span>{label}</span></div><p class="eyebrow label">{label} / Atualizado em 08.09.2026</p><h1>{title}</h1><p>{desc}</p></section>'
    privacy='''<section><h2>Por que tratamos dados</h2><p>A MATRIZ usa as informações do contato para responder à sua solicitação, entender o projeto e preparar uma proposta quando necessário. O formulário não inscreve você em campanhas de marketing.</p></section><section><h2>O que o formulário solicita</h2><p>Nome, email, tipo de projeto e descrição do problema. Empresa, WhatsApp e investimento previsto são opcionais. Evite enviar informações sensíveis ou dados de outras pessoas sem necessidade.</p></section><section><h2>Como o envio funciona</h2><p>O Web3Forms processa o formulário e encaminha a mensagem ao contato responsável pelo site. Esse serviço utiliza infraestrutura e mecanismos de proteção contra abuso, com possibilidade de processamento em outros países. Sua política informa retenção de envios de até três anos, salvo prazo menor do plano ou exclusão anterior.</p><p>Consulte a <a href="https://web3forms.com/privacy" target="_blank" rel="noopener noreferrer">política de privacidade do Web3Forms</a>. As mensagens recebidas pela MATRIZ são usadas durante o atendimento e a relação comercial; sua exclusão pode ser solicitada, observadas obrigações de conservação aplicáveis.</p></section><section><h2>Navegação, armazenamento e terceiros</h2><p>O site não inclui publicidade, pixels de marketing ou analytics próprios. Fontes, scripts e imagens são servidos localmente. A página de contato guarda apenas o horário da última tentativa no armazenamento da sessão do navegador para limitar envios repetidos; o texto do formulário não é copiado para esse armazenamento.</p><p>A hospedagem e o serviço de formulário podem tratar registros técnicos, como IP, horário e informações do navegador, para entrega e segurança. Links externos, como GitHub e LinkedIn, seguem as políticas dos respectivos serviços.</p></section><section><h2>Seus direitos e seu contato</h2><p>Você pode solicitar informações sobre o tratamento, acesso, correção ou exclusão dos seus dados e exercer outros direitos aplicáveis. Utilize o <a href="contact.html?service=outro">formulário de contato</a>, identificando a solicitação como privacidade, ou o <a href="https://www.linkedin.com/in/gabriel-santana-b3654622a/" target="_blank" rel="noopener noreferrer">LinkedIn de contato</a>.</p><p>Podemos pedir informações proporcionais para confirmar sua identidade e proteger os dados. Veja também as <a href="https://www.gov.br/anpd/pt-br/assuntos/titular-de-dados-1/direito-dos-titulares" target="_blank" rel="noopener noreferrer">orientações da ANPD sobre os direitos dos titulares</a>.</p></section>'''
    write_page('privacy.html','Privacidade — MATRIZ','Como a MATRIZ trata os dados de contato, quais serviços participam do envio e como solicitar acesso, correção ou exclusão.',f'<div class="container">{intro("Privacidade","Clareza também<br>sobre seus dados.","Esta página descreve o que acontece ao navegar no site e enviar uma mensagem.")}<div class="privacy-layout">{privacy}</div></div>')
    security='''<section><h2>Uma superfície pequena</h2><p>Este site institucional é estático. Não possui banco de dados de clientes, área administrativa ou autenticação. Os projetos apresentados têm arquiteturas próprias, descritas nas respectivas páginas.</p></section><section><h2>Cuidados implementados</h2><ul><li>Política de segurança de conteúdo restritiva em todas as páginas.</li><li>Scripts, fontes e imagens locais, sem bibliotecas de animação externas.</li><li>Validação de campos, limites de tamanho, honeypot e intervalo entre tentativas.</li><li>Tratamento de falhas e tempo limite no envio de contato.</li><li>Verificações automáticas de arquivos, links, metadados e padrões de credenciais antes da publicação.</li></ul></section><section><h2>Contato e limites da plataforma</h2><p>O formulário depende do Web3Forms para processamento e entrega. A proteção no navegador complementa o serviço; não substitui controles do servidor. O GitHub Pages limita a configuração de cabeçalhos HTTP, por isso o site também mantém a política de conteúdo em metadados HTML.</p></section><section><h2>Relatar uma vulnerabilidade</h2><p>Use o <a href="contact.html?service=evolucao">canal de contato</a> ou o LinkedIn informado no rodapé. Descreva a página e os passos de reprodução sem enviar senhas, dados pessoais ou informações privadas de terceiros.</p><p>A documentação técnica está no <a href="https://github.com/GabrielSantanaBR/dataforge-portfolio/blob/main/SECURITY.md" target="_blank" rel="noopener noreferrer">SECURITY.md do repositório</a>.</p></section>'''
    write_page('security.html','Segurança — MATRIZ','Controles de segurança do site institucional e canal para relatar vulnerabilidades.',f'<div class="container">{intro("Segurança","Confiança se constrói<br>com atenção técnica.","Controles, limites e um canal para informar problemas.")}<div class="privacy-layout">{security}</div></div>')
    portfolio=f'''<div class="container"><section class="page-hero"><div class="breadcrumb"><a href="index.html">MATRIZ</a><span>/</span><span>Portfólio</span></div><p class="eyebrow label">Explore nosso trabalho</p><h1>Projetos com<br><span class="accent">ideia e construção.</span></h1><p>Interfaces, sistemas e soluções de dados. Cada projeto apresenta o que foi construído e seu estágio atual.</p><div class="actions"><a class="text-link" href="#projetos">Ver os cases <span aria-hidden="true">↓</span></a><a class="text-link" href="#repertorio">Explorar o código <span aria-hidden="true">↓</span></a></div></section><section class="case-section" id="projetos"><h2>Projetos em destaque</h2><div class="project-list">{''.join(case_tile(p) for p in FEATURED)}</div></section><section class="case-section upcoming-project"><div><p class="eyebrow label">Em desenvolvimento</p><h2>SICMA</h2><p>Java e Spring Boot. Acompanhe o próximo projeto.</p></div><a class="button secondary" href="sicma.html">Conhecer o projeto <span aria-hidden="true">↗</span></a></section><section class="case-section" id="repertorio"><h2>Código dos projetos</h2><p>Acesse os repositórios da seleção.</p>{repertoire_rows()}<details class="selection-notes"><summary>Como selecionamos os projetos</summary><p>Esta seleção prioriza produtos com interface, regras de negócio, integração, automação ou análise de dados documentadas. Exercícios de cursos, forks e práticas introdutórias ficaram fora do portfólio comercial.</p><p>O SICMA aparece separadamente como projeto em desenvolvimento. O estágio de cada case acompanha sua apresentação; capturas adaptadas ou anonimizadas são identificadas nas páginas dos projetos.</p></details></section></div>{cta()}'''
    write_page('repertoire.html','Portfólio completo — MATRIZ','Explore os projetos, as interfaces e o repertório técnico da MATRIZ, com fontes e estágios de desenvolvimento.',portfolio)

def utility_pages():
    write_page('thanks.html','Mensagem enviada — MATRIZ','Confirmação de envio do contato para a MATRIZ.',f'<section class="container simple-page">{brand()}<p class="eyebrow label">Próximo passo: entender seu projeto</p><h1>Contexto recebido.<br><span class="accent">Vamos construir a conversa.</span></h1><p>Sua mensagem foi aceita pelo serviço de envio. Vamos analisar o cenário e retornar pelo contato informado.</p><div class="actions">{action("index.html","Voltar ao início",True)}{action("index.html#projetos","Explorar projetos")}</div></section>',noindex=True)
    write_page('404.html','Página não encontrada — MATRIZ','Não encontramos este endereço. Explore as soluções e projetos da MATRIZ.',f'<section class="container simple-page"><p class="eyebrow label">404 / Caminho não encontrado</p><h1>Vamos encontrar<br><span class="accent">o próximo caminho.</span></h1><p>A página pode ter mudado de endereço. As soluções, projetos e canais de contato continuam disponíveis.</p><div class="actions">{action("index.html","Voltar ao início",True)}{action("index.html#projetos","Ver projetos")}</div></section>',noindex=True)
    write_page('project.html','Projetos — MATRIZ','Explore as páginas dos projetos da MATRIZ.',f'<section class="container simple-page" data-legacy-project><p class="eyebrow label">Projetos MATRIZ</p><h1>Cada projeto,<br><span class="accent">uma história própria.</span></h1><p id="legacy-project-message">Os projetos agora têm páginas individuais. Escolha uma solução para conhecer a construção.</p><a class="button primary" id="legacy-project-link" href="index.html#projetos">Explorar projetos ↗</a><ul class="feature-list">'+''.join(f'<li><a href="{p["page"]}">{e(p["name"])}</a></li>' for p in VISIBLE_CASES)+'</ul></section>',noindex=True)

def metadata():
    urls=['', 'prices.html','contact.html','privacy.html','security.html','repertoire.html']+[p['page'] for p in VISIBLE_CASES]
    ET.register_namespace('','http://www.sitemaps.org/schemas/sitemap/0.9')
    sitemap=ET.Element('{http://www.sitemaps.org/schemas/sitemap/0.9}urlset')
    for path in urls:
        u=ET.SubElement(sitemap,'url');ET.SubElement(u,'loc').text=BASE+path;ET.SubElement(u,'lastmod').text=DATE
    ET.indent(sitemap);ET.ElementTree(sitemap).write(ROOT/'sitemap.xml',encoding='utf-8',xml_declaration=True)
    (ROOT/'robots.txt').write_text(f'User-agent: *\nAllow: /\nDisallow: /dataforge-portfolio/thanks.html\nDisallow: /dataforge-portfolio/project.html\nSitemap: {BASE}sitemap.xml\n')
    (ROOT/'site.webmanifest').write_text(json.dumps({'name':'MATRIZ — Tecnologia aplicada','short_name':'MATRIZ','lang':'pt-BR','start_url':'./','scope':'./','display':'browser','background_color':'#0A0B0D','theme_color':'#0A0B0D','icons':[{'src':'assets/brand/logo-matriz.png','sizes':'1254x1254','type':'image/png','purpose':'any'}]},ensure_ascii=False,indent=2)+'\n')
    (ROOT/'.well-known').mkdir(exist_ok=True)
    (ROOT/'.well-known/security.txt').write_text(f'Contact: {BASE}contact.html\nContact: {LINKEDIN}\nCanonical: {BASE}.well-known/security.txt\nPreferred-Languages: pt-BR, en\nExpires: 2027-09-01T00:00:00Z\nPolicy: {BASE}security.html\n')
    (ROOT/'.nojekyll').touch()

if __name__=='__main__':
    contact_bundle()
    home();project_pages();contact_page();services_page();editorial_pages();utility_pages();metadata()
    print(f'Rendered {len(CASES)} project pages, {len(FEATURED)} featured cases and {len(PROJECTS)} repertoire records.')
